<?php
declare(strict_types=1);
function ptTreeFields():array{$f=json_decode(file_get_contents(__DIR__.'/tree_fields.json'),true,64,JSON_THROW_ON_ERROR);foreach(['lat_wgs84','lng_wgs84','x_sjtsk','y_sjtsk'] as $k)unset($f[$k]);return $f;}
function ptAreaFields():array{
 $out=[];foreach(['name'=>'Název','state_note'=>'Popis stavu','treatments'=>'Navržené zásahy','note'=>'Poznámka','height_min'=>'Výška od (m)','height_max'=>'Výška do (m)','planted'=>'Datum výsadby','measured_at'=>'Datum měření','last_insp_at'=>'Poslední kontrola','next_insp_at'=>'Další kontrola','suitability'=>'Vhodnost','management'=>'Pěstební stav','biology'=>'Biologická hodnota','attractiveness'=>'Atraktivita umístění','urgency'=>'Naléhavost','status'=>'Stav'] as $k=>$l)$out[$k]=['label'=>$l,'type'=>str_contains($k,'height')?'number':(in_array($k,['planted','measured_at','last_insp_at','next_insp_at'])?'date':'text'),'options'=>[]];
 foreach(['status'=>['existing','removed'],'suitability'=>['','invasive','undesirable','other','suitable'],'management'=>['','neglected','irregular','managed'],'biology'=>['','low','medium','high'],'attractiveness'=>['','low','medium','high'],'urgency'=>['','0','1','2','3']] as $k=>$v){$out[$k]['type']='select';$out[$k]['options']=array_combine($v,$v);}
 $labels=['existing'=>'Existující','removed'=>'Odstraněný','invasive'=>'Invazivní','undesirable'=>'Nežádoucí','other'=>'Ostatní','suitable'=>'Vhodný','neglected'=>'Zanedbaný','irregular'=>'Průběžně nevychovávaný','managed'=>'Vychovávaný','low'=>'Nízká','medium'=>'Střední','high'=>'Vysoká',''=>'Nehodnoceno'];foreach($out as &$f)if($f['type']==='select')foreach($f['options'] as $v=>&$label)$label=$labels[$v]??(string)$v;unset($f,$label);
 return $out;
}
function ptCatalog():array{global $mysqli;static $cached=null;if($cached!==null)return $cached;$t=ptTreeFields();$ordered=[];foreach($mysqli->query('SHOW COLUMNS FROM trees')->fetch_all(MYSQLI_ASSOC) as $column){$key=$column['Field'];if(isset($t[$key]))$ordered[$key]=$t[$key];}$t=$ordered+$t;unset($t['usr_id'],$t['lat_wgs84'],$t['lng_wgs84'],$t['x_sjtsk'],$t['y_sjtsk']);$a=ptAreaFields();unset($a['status']);$a['species']=['label'=>'Druhové složení'];$a['components']=['label'=>'Charaktery a výměry AOPK'];return $cached=['trees'=>$t,'areas'=>$a];}
function ptHidden($data):array{if(!is_array($data))throw new InvalidArgumentException('Neplatná struktura.');$out=[];foreach(ptCatalog() as $kind=>$known){$list=$data[$kind]??null;if(!is_array($list)||count($list)>100)throw new InvalidArgumentException('Neplatná pole struktury.');foreach($list as $key)if(!is_string($key)||!isset($known[$key]))throw new InvalidArgumentException('Neznámé pole struktury.');$out[$kind]=array_values(array_unique($list));}return $out;}
